  "steps": [
    {
      "name": "IDLE",
      "entry": "Pallet leaves ST30 (X33 falling edge resets M310, M311) or initial state",
      "exit": "Pallet in ST30 (X33), guard door closed (X32), E-stop healthy (X0), and no latched result (ANI M310, ANI M311)"
    },
    {
      "name": "TESTING (HV ENABLED)",
      "entry": "X33 AND X32 AND X0 AND NOT M310 AND NOT M311 (turns on Y30 and Y31)",
      "exit": "Tester reports PASS (X30) or FAIL (X31), or interlock lost (X32 or X0 opens)"
    },
    {
      "name": "RESULT LATCHED",
      "entry": "PASS signal received (X30 sets M310) or FAIL signal received (X31 sets M311)",
      "exit": "Pallet leaves ST30 (X33 falling edge resets M310 and M311)"
    }
  ],
  "interlocks": [
    {
      "cause": "Guard door open (NOT X32) or E-stop chain lost (NOT X0)",
      "effect": "De-energise HiPot start/HV enable (Y30) and HV beacon (Y31) immediately"
    },
    {
      "cause": "HiPot result latched (M310 or M311 ON)",
      "effect": "De-energise HiPot start/HV enable (Y30) and HV beacon (Y31)"
    },
    {
      "cause": "Pallet leaves ST30 (falling edge of X33)",
      "effect": "Reset HiPot PASS (M310) and HiPot FAIL (M311)"
    }
  ],
